    async def fetch_currencies(self, params: dict = {}) -> Currencies:
        """
        fetches all available currencies on an exchange - every instrument base, the usd quote and the collateral asset

        https://docs.polymarket.com/perps/market-data

        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: an associative dictionary of currencies
        """
        promises = [
            self.publicGetInfoInstruments(params),
            self.publicGetInfoAssets(params),
        ]
        responses = await asyncio.gather(*promises)
        instruments = self.safe_list(responses, 0, [])
        assets = self.safe_list(responses, 1, [])
        result = {}
        for i in range(0, len(instruments)):
            instrument = instruments[i]
            baseId = self.safe_string(instrument, 'base_asset')
            if baseId is None:
                continue
            code = self.safe_currency_code(baseId)
            if not (code in result):
                # the venue tags each underlying with a category - only the
                # crypto ones are unified as crypto, equities, commodities and
                # indices map onto the other currency type
                category = self.safe_string(instrument, 'category')
                currencyType = 'crypto' if (category == 'crypto') else 'other'
                result[code] = self.safe_currency_structure({
                    'id': baseId,
                    'code': code,
                    'name': baseId,
                    'info': instrument,
                    'active': True,
                    'deposit': False,
                    'withdraw': False,
                    'fee': None,
                    'precision': self.parse_number(self.parse_precision(self.safe_string(instrument, 'quantity_decimals'))),
                    'type': currencyType,
                    'networks': {},
                })
        # every instrument quotes using usd
        result['USD'] = self.safe_currency_structure({
            'id': 'USD',
            'code': 'USD',
            'name': 'USD',
            'info': {},
            'active': True,
            'deposit': False,
            'withdraw': False,
            'fee': None,
            'precision': self.parse_number('0.01'),
            'type': 'fiat',
            'networks': {},
        })
        for i in range(0, len(assets)):
            asset = assets[i]
            currencyId = self.safe_string(asset, 'asset')
            if currencyId is None:
                continue
            code = self.safe_currency_code(currencyId)
            result[code] = self.safe_currency_structure({
                'id': currencyId,
                'code': code,
                'name': currencyId,
                'info': asset,
                'active': True,
                'deposit': True,
                'withdraw': True,
                'fee': self.safe_number(asset, 'withdrawal_fee'),
                'precision': self.parse_number(self.parse_precision(self.safe_string(asset, 'decimals'))),
                'type': 'crypto',
                'networks': {},
            })
        return result

