    def parse_market(self, market: dict) -> Market:
        numericId = self.safe_string(market, 'instrument_id')
        venueSymbol = self.safe_string(market, 'symbol')
        baseId = self.safe_string(market, 'base_asset')
        # prices are denominated using USD while pUSD is the 1:1 collateral and settlement token
        settleId = self.safe_string(market, 'quote_asset')
        parts = venueSymbol.split('-')
        quoteId = self.safe_string(parts, 1, 'USD')
        base = self.safe_currency_code(baseId)
        quote = self.safe_currency_code(quoteId)
        settle = self.safe_currency_code(settleId)
        crossAllowed = not (self.safe_bool(market, 'isolated_only', False))
        return self.safe_market_structure({
            'id': numericId,
            'symbol': base + '/' + quote + ':' + settle,
            'base': base,
            'quote': quote,
            'settle': settle,
            'baseId': baseId,
            'quoteId': quoteId,
            'settleId': settleId,
            'type': 'swap',
            'spot': False,
            'margin': False,
            'swap': True,
            'future': False,
            'option': False,
            # the venue lists tradable instruments only, an exchange wide
            # halt surfaces through fetchStatus via the cancel_only flag
            'active': True,
            'contract': True,
            'linear': True,
            'inverse': False,
            # tier-0 rates from GET /v1/info/fees, shared by every category
            'taker': self.parse_number('0.0004'),
            'maker': self.parse_number('0.000125'),
            'contractSize': self.parse_number('1'),
            'expiry': None,
            'expiryDatetime': None,
            'strike': None,
            'optionType': None,
            'marginModes': {
                'cross': crossAllowed,
                'isolated': True,
            },
            'precision': {
                'amount': self.parse_number(self.parse_precision(self.safe_string(market, 'quantity_decimals'))),
                'price': self.parse_number(self.parse_precision(self.safe_string(market, 'price_decimals'))),
            },
            'limits': {
                'leverage': {
                    'min': self.parse_number('1'),
                    'max': self.safe_number(market, 'max_leverage'),
                },
                'amount': {
                    'min': None,
                    'max': None,
                },
                'price': {
                    'min': None,
                    'max': None,
                },
                'cost': {
                    'min': self.safe_number(market, 'min_notional'),
                    'max': self.safe_number(market, 'max_limit_notional'),
                },
            },
            'created': None,
            'info': market,
        })

    async def fetch_ticker(self, symbol: str, params: dict = {}) -> Ticker:
        """
        fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market, merging the ticker, statistics and best bid and ask endpoints

        https://docs.polymarket.com/perps/market-data

        :param str symbol: unified symbol of the market to fetch the ticker for
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a `ticker structure <https://docs.ccxt.com/#/?id=ticker-structure>`
        """
        await self.load_markets()
        market = self.market(symbol)
        symbolResolved = market['symbol']
        # the tickers and statistics endpoints ignore the documented
        # instrument_id filter and always answer with every instrument, so
        # the single-market call reuses the bulk fetch and selects one row
        tickers = await self.fetch_tickers([symbolResolved], params)
        ticker = self.safe_dict(tickers, symbolResolved)
        if ticker is None:
            raise BadSymbol(self.id + ' fetchTicker() could not find a ticker for ' + symbolResolved)
        return ticker

    async def fetch_tickers(self, symbols: Strings = None, params: dict = {}) -> Tickers:
        """
        fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market, merging the ticker, statistics and best bid and ask endpoints

        https://docs.polymarket.com/perps/market-data

        :param str[] [symbols]: unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a dictionary of `ticker structures <https://docs.ccxt.com/#/?id=ticker-structure>`
        """
        await self.load_markets()
        symbolsNormalized = self.market_symbols(symbols)
        promises = [
            self.publicGetInfoTickers(params),
            self.publicGetInfoStatistics(params),
            self.publicGetInfoBbo(params),
        ]
        responses = await asyncio.gather(*promises)
        #
        # tickers
        #
        #     [
        #         {
        #             "instrument_id": 1,
        #             "symbol": "SP500-USD",
        #             "index_price": "7713.1",
        #             "mark_price": "7715",
        #             "last_price": "7714",
        #             "mid_price": "7715",
        #             "open_interest": "1101.82729",
        #             "funding_rate": "0.00000625",
        #             "next_funding": 1788548400000,
        #             "timestamp": 1788546972857
        #         }
        #     ]
        #
        # statistics
        #
        #     [
        #         {
        #             "instrument_id": 1,
        #             "symbol": "SP500-USD",
        #             "volume": "2087643.9565559996",
        #             "open_price": "7754.5",
        #             "klines": [ [ 1788458400000, "7754.5", "7754.5", "7751.4", "7751.4", "0.39184", 3 ] ]
        #         }
        #     ]
        #
        # bbo
        #
        #     [
        #         {
        #             "instrument_id": 1,
        #             "bid_price": "7715",
        #             "bid_quantity": "22.63803",
        #             "ask_price": "7715.1",
        #             "ask_quantity": "0.95534",
        #             "timestamp": 1788546975038
        #         }
        #     ]
        #
        merged = {}
        statistics = self.safe_list(responses, 1, [])
        for i in range(0, len(statistics)):
            entry = statistics[i]
            instrumentId = self.safe_string(entry, 'instrument_id')
            # the 24 hourly kline rows are dropped from the merged payload to keep tickers light, candles are served by fetchOHLCV
            merged[instrumentId] = self.omit(entry, 'klines')
        bbos = self.safe_list(responses, 2, [])
        for i in range(0, len(bbos)):
            entry = bbos[i]
            instrumentId = self.safe_string(entry, 'instrument_id')
            previous = self.safe_dict(merged, instrumentId, {})
            # the tickers endpoint timestamp wins the merge below because most unified fields come from it - bbo rows carry a slightly newer sampling time
            merged[instrumentId] = self.extend(previous, entry)
        tickers = self.safe_list(responses, 0, [])
        result = []
        for i in range(0, len(tickers)):
            entry = tickers[i]
            instrumentId = self.safe_string(entry, 'instrument_id')
            previous = self.safe_dict(merged, instrumentId, {})
            result.append(self.extend(previous, entry))
        return self.parse_tickers(result, symbolsNormalized)

    def parse_ticker(self, ticker: dict, market: Market = None) -> Ticker:
        #
        # merged row assembled by fetchTickers from the tickers, statistics and bbo endpoints
        #
        #     {
        #         "instrument_id": 1,
        #         "symbol": "SP500-USD",
        #         "volume": "2087643.9565559996",
        #         "open_price": "7754.5",
        #         "bid_price": "7715",
        #         "bid_quantity": "22.63803",
        #         "ask_price": "7715.1",
        #         "ask_quantity": "0.95534",
        #         "index_price": "7713.1",
        #         "mark_price": "7715",
        #         "last_price": "7714",
        #         "mid_price": "7715",
        #         "open_interest": "1101.82729",
        #         "funding_rate": "0.00000625",
        #         "next_funding": 1788548400000,
        #         "timestamp": 1788546972857
        #     }
        #
        marketId = self.safe_string(ticker, 'instrument_id')
        marketResolved = self.safe_market(marketId, market)
        timestamp = self.safe_integer(ticker, 'timestamp')
        return self.safe_ticker({
            'symbol': marketResolved['symbol'],
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'high': None,
            'low': None,
            'bid': self.safe_string(ticker, 'bid_price'),
            'bidVolume': self.safe_string(ticker, 'bid_quantity'),
            'ask': self.safe_string(ticker, 'ask_price'),
            'askVolume': self.safe_string(ticker, 'ask_quantity'),
            'vwap': None,
            'open': self.safe_string(ticker, 'open_price'),
            'close': self.safe_string(ticker, 'last_price'),
            'last': self.safe_string(ticker, 'last_price'),
            'previousClose': None,
            'change': None,
            'percentage': None,
            'average': None,
            'baseVolume': None,
            # the statistics volume is denominated using pUSD, verified against the sum of hourly candle base volumes
            'quoteVolume': self.safe_string(ticker, 'volume'),
            'markPrice': self.safe_string(ticker, 'mark_price'),
            'indexPrice': self.safe_string(ticker, 'index_price'),
            'info': ticker,
        }, marketResolved)

    async def fetch_bids_asks(self, symbols: Strings = None, params: dict = {}) -> Tickers:
        """
        fetches the best bid and ask price and volume for multiple markets

        https://docs.polymarket.com/perps/market-data

        :param str[] [symbols]: unified symbols of the markets to fetch the bids and asks for, all markets are returned if not assigned
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a dictionary of `ticker structures <https://docs.ccxt.com/#/?id=ticker-structure>`
        """
        await self.load_markets()
        symbolsNormalized = self.market_symbols(symbols)
        response = await self.publicGetInfoBbo(params)
        #
        #     [
        #         {
        #             "instrument_id": 1,
        #             "bid_price": "7715",
        #             "bid_quantity": "22.63803",
        #             "ask_price": "7715.1",
        #             "ask_quantity": "0.95534",
        #             "timestamp": 1788546975038
        #         }
        #     ]
        #
        return self.parse_tickers(response, symbolsNormalized)

    async def fetch_order_book(self, symbol: str, limit: Int = None, params: dict = {}) -> OrderBook:
        """
        fetches information on open orders with bid(buy) and ask(sell) prices, volumes and other data

        https://docs.polymarket.com/perps/market-data

        :param str symbol: unified symbol of the market to fetch the order book for
        :param int [limit]: the maximum amount of order book entries to return, must be one of 10, 100, 500 or 1000, the default is 100
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: A dictionary of `order book structures <https://docs.ccxt.com/#/?id=order-book-structure>` indexed by market symbols
        """
        await self.load_markets()
        market = self.market(symbol)
        request = {
            'instrument_id': market['id'],
        }
        if limit is not None:
            request['depth'] = limit
        response = await self.publicGetInfoBook(self.extend(request, params))
        #
        #     {
        #         "instrument_id": 1,
        #         "bids": [ [ "7745.1", "0.319" ] ],
        #         "asks": [ [ "7745.2", "53.36141" ] ],
        #         "timestamp": 1788524545112,
        #         "sequence": 35631219797
        #     }
        #
        timestamp = self.safe_integer(response, 'timestamp')
        orderbook = self.parse_order_book(response, market['symbol'], timestamp)
        orderbook['nonce'] = self.safe_integer(response, 'sequence')
        return orderbook

    async def fetch_trades(self, symbol: str, since: Int = None, limit: Int = None, params: dict = {}) -> list[Trade]:
        """
        get the list of the most recent trades for a particular symbol

        https://docs.polymarket.com/perps/market-data

        :param str symbol: unified symbol of the market to fetch trades for
        :param int [since]: timestamp in ms of the earliest trade to fetch
        :param int [limit]: the maximum number of trades to fetch, the venue serves at most 100 per request
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param int [params.until]: timestamp in ms of the latest trade to fetch
        :returns Trade[]: a list of `trade structures <https://docs.ccxt.com/#/?id=public-trades>`
        """
        await self.load_markets()
        market = self.market(symbol)
        request = {
            'instrument_id': market['id'],
        }
        if since is not None:
            request['start_timestamp'] = since
        until = self.safe_integer(params, 'until')
        paramsOmitted = params
        if until is not None:
            paramsOmitted = self.omit(paramsOmitted, 'until')
            request['end_timestamp'] = until
        response = await self.publicGetInfoTrades(self.extend(request, paramsOmitted))
        #
        #     {
        #         "data": [
        #             {
        #                 "trade_id": 3738280849593744,
        #                 "instrument_id": 1,
        #                 "side": "long",
        #                 "price": "7714",
        #                 "quantity": "0.00136",
        #                 "timestamp": 1788546565789,
        #                 "hash": "0x"
        #             }
        #         ],
        #         "more": true
        #     }
        #
        data = self.safe_list(response, 'data', [])
        return self.parse_trades(data, market, since, limit)

    def parse_trade(self, trade: dict, market: Market = None) -> Trade:
        #
        #     {
        #         "trade_id": 3738280849593744,
        #         "instrument_id": 1,
        #         "side": "long",
        #         "price": "7714",
        #         "quantity": "0.00136",
        #         "timestamp": 1788546565789,
        #         "hash": "0x"
        #     }
        #
        marketId = self.safe_string_2(trade, 'instrument_id', 'iid')
        marketResolved = self.safe_market(marketId, market)
        timestamp = self.safe_integer_2(trade, 'timestamp', 'ts')
        side = self.safe_string_lower(trade, 'side')
        if side == 'long':
            side = 'buy'
        elif side == 'short':
            side = 'sell'
        isTaker = self.safe_bool(trade, 'taker')
        takerOrMaker = None
        if isTaker is not None:
            takerOrMaker = 'taker' if (isTaker) else 'maker'
        feeCost = self.safe_string(trade, 'fee')
        fee = None
        if feeCost is not None:
            feeCurrencyId = self.safe_string_2(trade, 'fee_asset', 'fea')
            fee = {
                'cost': feeCost,
                'currency': self.safe_currency_code(feeCurrencyId),
            }
        return self.safe_trade({
            'id': self.safe_string_2(trade, 'trade_id', 'tid'),
            'info': trade,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'symbol': marketResolved['symbol'],
            'order': self.safe_string_2(trade, 'order_id', 'oid'),
            'type': None,
            'side': side,
            'takerOrMaker': takerOrMaker,
            'price': self.safe_string_2(trade, 'price', 'p'),
            'amount': self.safe_string_2(trade, 'quantity', 'qty'),
            'cost': None,
            'fee': fee,
        }, marketResolved)

    async def fetch_ohlcv(self, symbol: str, timeframe='1m', since: Int = None, limit: Int = None, params: dict = {}) -> list[list]:
        """
        fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market

        https://docs.polymarket.com/perps/market-data

        :param str symbol: unified symbol of the market to fetch OHLCV data for
        :param str timeframe: the length of time each candle represents
        :param int [since]: timestamp in ms of the earliest candle to fetch
        :param int [limit]: the maximum amount of candles to fetch, the venue serves at most 1000 per request
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param int [params.until]: timestamp in ms of the latest candle to fetch
        :param boolean [params.paginate]: default False, when True will automatically paginate by calling the endpoint multiple times
        :returns int[][]: A list of candles ordered as timestamp, open, high, low, close, volume
        """
        await self.load_markets()
        paginate = False
        paramsOmitted = params
        paginate, paramsOmitted = self.handle_option_and_params(paramsOmitted, 'fetchOHLCV', 'paginate')
        if paginate:
            return await self.fetch_paginated_call_deterministic('fetchOHLCV', symbol, since, limit, timeframe, paramsOmitted, 1000)
        market = self.market(symbol)
        request = {
            'instrument_id': market['id'],
            'interval': self.safe_string(self.timeframes, timeframe, timeframe),
        }
        until = self.safe_integer(paramsOmitted, 'until')
        if until is not None:
            paramsOmitted = self.omit(paramsOmitted, 'until')
            request['end_timestamp'] = until
        duration = self.parse_timeframe(timeframe) * 1000
        if since is not None:
            request['start_timestamp'] = since
        else:
            # the venue requires an explicit range start - the window covers
            # exactly the requested number of candle bins including the
            # current one, so the newest candle never falls off the range
            end = until if (until is not None) else self.milliseconds()
            requestedLimit = limit if (limit is not None) else 100
            request['start_timestamp'] = end - (requestedLimit - 1) * duration
        response = await self.publicGetInfoKlines(self.extend(request, paramsOmitted))
        #
        #     {
        #         "data": [
        #             [ 1788458400000, "7754.5", "7754.5", "7751.4", "7751.4", "0.39184", 3 ]
        #         ],
        #         "more": false
        #     }
        #
        data = self.safe_list(response, 'data', [])
        return self.parse_ohlcvs(data, market, timeframe, since, limit)

    def parse_ohlcv(self, ohlcv: object, market: Market = None) -> list:
        #
        # rows carry the timestamp, open, high, low, close, base volume and the trade count
        #
        #     [ 1788458400000, "7754.5", "7754.5", "7751.4", "7751.4", "0.39184", 3 ]
        #
        return [
            self.safe_integer(ohlcv, 0),
            self.safe_number(ohlcv, 1),
            self.safe_number(ohlcv, 2),
            self.safe_number(ohlcv, 3),
            self.safe_number(ohlcv, 4),
            self.safe_number(ohlcv, 5),
        ]

    async def fetch_funding_rate(self, symbol: str, params: dict = {}) -> FundingRate:
        """
        fetch the current funding rate

        https://docs.polymarket.com/perps/market-data

        :param str symbol: unified market symbol
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a `funding rate structure <https://docs.ccxt.com/#/?id=funding-rate-structure>`
        """
        await self.load_markets()
        market = self.market(symbol)
        symbolResolved = market['symbol']
        # the tickers endpoint ignores the documented instrument_id filter
        # and always answers with every instrument, so the single-market call
        # reuses the bulk fetch and selects the requested row
        fundingRates = await self.fetch_funding_rates([symbolResolved], params)
        fundingRate = self.safe_dict(fundingRates, symbolResolved)
        if fundingRate is None:
            raise BadSymbol(self.id + ' fetchFundingRate() could not find the funding rate for ' + symbolResolved)
        return fundingRate

    async def fetch_funding_rates(self, symbols: Strings = None, params: dict = {}) -> FundingRates:
        """
        fetches the current funding rates for multiple markets

        https://docs.polymarket.com/perps/market-data

        :param str[] [symbols]: unified market symbols
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a dictionary of `funding rate structures <https://docs.ccxt.com/#/?id=funding-rate-structure>`
        """
        await self.load_markets()
        symbolsNormalized = self.market_symbols(symbols)
        response = await self.publicGetInfoTickers(params)
        result = self.parse_funding_rates(response)
        return self.index_by(self.filter_by_array(result, 'symbol', symbolsNormalized, False), 'symbol')

    def parse_funding_rate(self, contract: object, market: Market = None) -> FundingRate:
        #
        #     {
        #         "instrument_id": 1,
        #         "symbol": "SP500-USD",
        #         "index_price": "7713.1",
        #         "mark_price": "7715",
        #         "last_price": "7714",
        #         "mid_price": "7715",
        #         "open_interest": "1101.82729",
        #         "funding_rate": "0.00000625",
        #         "next_funding": 1788548400000,
        #         "timestamp": 1788546972857
        #     }
        #
        marketId = self.safe_string(contract, 'instrument_id')
        marketResolved = self.safe_market(marketId, market)
        timestamp = self.safe_integer(contract, 'timestamp')
        nextFundingTimestamp = self.safe_integer(contract, 'next_funding')
        interval = self.safe_string(marketResolved['info'], 'funding_interval')
        return {
            'info': contract,
            'symbol': marketResolved['symbol'],
            'markPrice': self.safe_number(contract, 'mark_price'),
            'indexPrice': self.safe_number(contract, 'index_price'),
            'interestRate': None,
            'estimatedSettlePrice': None,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'fundingRate': self.safe_number(contract, 'funding_rate'),
            'fundingTimestamp': None,
            'fundingDatetime': None,
            'nextFundingRate': None,
            'nextFundingTimestamp': nextFundingTimestamp,
            'nextFundingDatetime': self.iso8601(nextFundingTimestamp),
            'previousFundingRate': None,
            'previousFundingTimestamp': None,
            'previousFundingDatetime': None,
            'interval': interval,
        }

    async def fetch_funding_rate_history(self, symbol: Str = None, since: Int = None, limit: Int = None, params: dict = {}) -> list[FundingRateHistory]:
        """
        fetches historical funding rate prices

        https://docs.polymarket.com/perps/market-data

        :param str symbol: unified symbol of the market to fetch the funding rate history for
        :param int [since]: timestamp in ms of the earliest funding rate to fetch
        :param int [limit]: the maximum amount of funding rate structures to fetch, the venue serves at most 100 per request
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param int [params.until]: timestamp in ms of the latest funding rate to fetch
        :param boolean [params.paginate]: default False, when True will automatically paginate by calling the endpoint multiple times
        :returns dict[]: a list of `funding rate structures <https://docs.ccxt.com/#/?id=funding-rate-history-structure>`
        """
        if symbol is None:
            raise ArgumentsRequired(self.id + ' fetchFundingRateHistory() requires a symbol argument')
        await self.load_markets()
        paginate = False
        paramsOmitted = params
        paginate, paramsOmitted = self.handle_option_and_params(paramsOmitted, 'fetchFundingRateHistory', 'paginate')
        if paginate:
            return await self.fetch_paginated_call_deterministic('fetchFundingRateHistory', symbol, since, limit, '1h', paramsOmitted, 100)
        market = self.market(symbol)
        request = {
            'instrument_id': market['id'],
        }
        if since is not None:
            request['start_timestamp'] = since
        until = self.safe_integer(paramsOmitted, 'until')
        if until is not None:
            paramsOmitted = self.omit(paramsOmitted, 'until')
            request['end_timestamp'] = until
        response = await self.publicGetInfoFunding(self.extend(request, paramsOmitted))
        #
        #     {
        #         "data": [
        #             { "funding_rate": "0.00000625", "timestamp": 1788544800063 }
        #         ],
        #         "more": false
        #     }
        #
        data = self.safe_list(response, 'data', [])
        rates = []
        for i in range(0, len(data)):
            entry = data[i]
            timestamp = self.safe_integer(entry, 'timestamp')
            rates.append({
                'info': entry,
                'symbol': market['symbol'],
                'fundingRate': self.safe_number(entry, 'funding_rate'),
                'timestamp': timestamp,
                'datetime': self.iso8601(timestamp),
            })
        sorted = self.sort_by(rates, 'timestamp')
        return self.filter_by_symbol_since_limit(sorted, market['symbol'], since, limit)

    async def fetch_open_interest(self, symbol: str, params: dict = {}) -> OpenInterest:
        """
        retrieves the open interest of a contract trading pair

        https://docs.polymarket.com/perps/market-data

        :param str symbol: unified market symbol
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: an `open interest structure <https://docs.ccxt.com/#/?id=open-interest-structure>`
        """
        await self.load_markets()
        market = self.market(symbol)
