    async def fetch_funding_history(self, symbol: Str = None, since: Int = None, limit: Int = None, params: dict = {}) -> list[FundingHistory]:
        """
        fetch the funding payments paid and received on the open positions of the account

        https://docs.polymarket.com/perps/trading

        :param str [symbol]: unified market symbol
        :param int [since]: timestamp in ms of the earliest funding payment
        :param int [limit]: the maximum number of funding payment structures to return
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param int [params.until]: timestamp in ms of the latest funding payment
        :returns dict[]: a list of `funding history structures <https://docs.ccxt.com/#/?id=funding-history-structure>`
        """
        await self.load_markets()
        await self.load_proxy_credentials()
        market = None
        request = {}
        if symbol is not None:
            symbolMarket = self.market(symbol)
            market = symbolMarket
            request['instrument_id'] = symbolMarket['id']
        if since is not None:
            request['start_timestamp'] = since
        until = self.safe_integer(params, 'until')
        paramsOmitted = params
        if until is not None:
            paramsOmitted = self.omit(paramsOmitted, 'until')
            request['end_timestamp'] = until
        response = await self.privateGetAccountFunding(self.extend(request, paramsOmitted))
        #
        #     {
        #         "data": [
        #             {
        #                 "id": 123,
        #                 "instrument_id": 6,
        #                 "size": "0.001",
        #                 "funding_rate": "0.0000125",
        #                 "funding_asset": "USDC",
        #                 "funding": "-0.01",
        #                 "timestamp": 1788546565789
        #             }
        #         ],
        #         "more": false
        #     }
        #
        data = self.safe_list(response, 'data', [])
        result = []
        for i in range(0, len(data)):
            entry = data[i]
            marketId = self.safe_string(entry, 'instrument_id')
            timestamp = self.safe_integer(entry, 'timestamp')
            result.append({
                'info': entry,
                'symbol': self.safe_symbol(marketId, market),
                'code': self.safe_currency_code(self.safe_string(entry, 'funding_asset')),
                'timestamp': timestamp,
                'datetime': self.iso8601(timestamp),
                'id': self.safe_string(entry, 'id'),
                'amount': self.safe_number(entry, 'funding'),
            })
        return self.filter_by_symbol_since_limit(result, symbol, since, limit)

    def parse_transaction_status(self, status: Str) -> Str:
        statuses = {
            'pending': 'pending',
            'confirmed': 'ok',
            'removed': 'failed',
            'failed': 'failed',
        }
        return self.safe_string(statuses, status, status)

    def parse_transaction(self, transaction: dict, currency: Currency = None) -> Transaction:
        #
        # deposit row
        #
        #     {
        #         "hash": "0x...",
        #         "asset": "USDC",
        #         "amount": "100",
        #         "from": "0x...",
        #         "to": "0x...",
        #         "status": "confirmed",
        #         "confirmations": 10,
        #         "required_confirmations": 10,
        #         "created_timestamp": 1788546565789,
        #         "confirmed_timestamp": 1788546570789
        #     }
        #
        # withdrawal row
        #
        #     {
        #         "withdraw_id": 123,
        #         "asset": "USDC",
        #         "amount": "100",
        #         "to": "0x...",
        #         "fee": "0.1",
        #         "status": "pending",
        #         "hash": "0x",
        #         "confirmations": 0,
        #         "required_confirmations": 10,
        #         "created_timestamp": 1788546565789
        #     }
        #
        withdrawId = self.safe_string(transaction, 'withdraw_id')
        type = 'withdrawal' if (withdrawId is not None) else 'deposit'
        currencyId = self.safe_string(transaction, 'asset')
        code = self.safe_currency_code(currencyId, currency)
        timestamp = self.safe_integer(transaction, 'created_timestamp')
        rawHash = self.safe_string(transaction, 'hash')
        # the venue reports the literal 0x prefix while the transaction is unmined
        txid = None if (rawHash == '0x') else rawHash
        feeCost = self.safe_string(transaction, 'fee')
        fee = None
        if feeCost is not None:
            fee = {
                'cost': self.parse_number(feeCost),
                'currency': code,
            }
        return {
            'info': transaction,
            'id': withdrawId,
            'txid': txid,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'network': None,
            'address': None,
            'addressTo': self.safe_string(transaction, 'to'),
            'addressFrom': self.safe_string(transaction, 'from'),
            'tag': None,
            'tagTo': None,
            'tagFrom': None,
            'type': type,
            'amount': self.safe_number(transaction, 'amount'),
            'currency': code,
            'status': self.parse_transaction_status(self.safe_string(transaction, 'status')),
            'updated': self.safe_integer(transaction, 'confirmed_timestamp'),
            'comment': None,
            'internal': False,
            'fee': fee,
        }

